// Exclusive ESP32 UART owner: accept only the full flow's tracked semantic session.
const INV=1;
if(String(env.get("INV"+INV+"_TRANSPORT")||"").toLowerCase()!=="esp32")return null;
const cmd=String(msg.command||msg._cmd||"").trim().toUpperCase();
if(!cmd||cmd[0]==="Q")return null; // QPIRI/QDOP readback comes from cache.
const session=flow.get("learn_session_inv"+INV);
const terminal=(reason)=>({inverterNum:INV,_learn_complete:true,_learn_success:false,payload:{reason,param:session?.param||null}});
if(!session||session.active!==true||String(session.currentCandidate?.command||"").toUpperCase()!==cmd)
  return [null,null,null]; // Never forward raw HA commands blindly.
if(String(env.get("INV"+INV+"_ESP_WRITE_ENABLED")||"false").toLowerCase()!=="true")
  return [null,null,terminal("esp_write_disabled")];
const mp={
 battery_bulk_voltage:["battery_bulk_voltage_v","battery_bulk_voltage"],
 battery_float_voltage:["battery_float_voltage_v","battery_float_voltage"],
 battery_under_voltage:["battery_under_voltage_v","battery_under_voltage"],
 battery_recharge_voltage:["battery_recharge_voltage_v","battery_recharge_voltage"],
 battery_re_discharge_voltage:["battery_re_discharge_voltage_v","battery_re_discharge_voltage"],
 max_charging_current:["max_charging_current_a","max_charging_current"],
 max_ac_charging_current:["max_ac_charging_current_a","max_ac_charging_current"],
 output_source_priority:["output_source_priority_code","output_source_priority_code"],
 charger_source_priority:["charger_source_priority_code","charger_source_priority_code"]
};
const fields=mp[session.param];
if(!fields)return [null,null,terminal("unsupported_semantic_parameter")];
const state=flow.get("inv"+INV+"_normalized_state")||{};
const q=state.params?.qpiri||{},old=Number(q[fields[1]]);
let value=Number(session.kind==="number"?session.requestedValue:session.currentCandidate?.expectedCode);
if(!Number.isFinite(old)||!Number.isFinite(value))return [null,null,terminal("missing_preview")];
if(!state._last_qpiri_ts || Date.now()-state._last_qpiri_ts>600000)
 return [null,null,terminal("stale_parameter_snapshot")];
const primary={
 battery_bulk_voltage:"PCVV",battery_float_voltage:"PBFT",battery_under_voltage:"PSDV",
 battery_recharge_voltage:"PBCV",battery_re_discharge_voltage:"PBDV",
 max_charging_current:"MNCHGC",max_ac_charging_current:"MUCHGC",
 output_source_priority:"POP",charger_source_priority:"PCP"
}[session.param];
if(!cmd.startsWith(primary)|| !/^[A-Z0-9.]+$/.test(cmd)||cmd.length>32){
 // This candidate cannot be a safe alias for this semantic setting.
 return [null,{inverterNum:INV,command:cmd,_raw_response:"NAK",payload:{nak:true,raw:"NAK"}},null];
}
const code=String(env.get("INV"+INV+"_ESP_CODE")||"");
const host=String(env.get("INV"+INV+"_ESP_HOST")||"");
const port=Number(env.get("INV"+INV+"_ESP_PORT")||18081);
if(code.length<8||!/^[a-zA-Z0-9.-]+$/.test(host)||port<1||port>65535)
 return [null,null,terminal("esp_not_configured")];
msg.inverterNum=INV;
msg.method="POST";msg.url="http://"+host+":"+port+"/api/v1/parameters/change";
msg.headers={"X-Setup-Code":code,"X-Write-Confirmed":"yes","Content-Type":"application/json"};
msg.payload=JSON.stringify({parameter:fields[0],old,value,confirmed:true,candidate:cmd});
msg._esp_learning_command=cmd;
msg._esp_learning_session=session.sessionId;
return [msg,null,null];

// Never retry an uncertain UART write. Only an explicitly verified
// firmware readback can generate ACK for the existing Learning RX Feedback.
const INV=1,session=flow.get("learn_session_inv"+INV);
if(!session||!session.active||session.sessionId!==msg._esp_learning_session)return null;
let d=msg.payload;
if(typeof d==="string"){try{d=JSON.parse(d);}catch(e){d=null;}}
if(msg.statusCode===200&&d?.verified===true&&d?.set_acknowledged===true){
 return [{inverterNum:INV,command:msg._esp_learning_command,_raw_response:"ACK",
 payload:{nak:false,raw:"ACK"}},null,null];
}
if(d?.result==="unsupported_candidate"||d?.result==="set_rejected_by_nak")
 return [null,{inverterNum:INV,command:msg._esp_learning_command,
 _raw_response:"NAK",payload:{nak:true,raw:"NAK"}},null];
// Any HTTP failure, timeout or unverified write leaves state uncertain.
// Do not send the next candidate or perform a second write.
return [null,null,{inverterNum:INV,_learn_complete:true,_learn_success:false,
 payload:{param:session.param,reason:"esp_edit_not_verified",result:d?.result||"http_failure"}}];

